const STUDENT_ENTRIES_CHANNEL = 'C0ATAQ8KFF1';
const FINANCE_LOG_CHANNEL = 'C0ATVRN4DDJ';

// Pull Slack trigger data
const triggerData = $('Slack Trigger — new message').item.json;

// Drop bot-sourced messages (including our own failure replies). Processing them
// created a self-referential loop where the warning text was extracted as a real
// Expense (exec 10650 landed a fake 422-rupee expense on the Davya ledger).
if (triggerData.bot_id || triggerData.subtype === 'bot_message' || triggerData.app_id) {
  return null;
}

const slackChannel = triggerData.channel || triggerData.event?.channel || '';
const slackTs = triggerData.ts || triggerData.event?.ts || '';
const rawInput = (triggerData.text || triggerData.event?.text || '').slice(0, 4000);

// Parse Gemini response
let gemini = null;
let parseError = null;
try {
  const geminiRaw = $input.item.json.body?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (geminiRaw) {
    gemini = JSON.parse(geminiRaw);
  } else {
    parseError = 'no candidates in Gemini response';
  }
} catch (e) {
  parseError = 'JSON parse error: ' + e.message;
}

// Check parse succeeded and has required fields
if (!gemini || !gemini.category || typeof gemini.amount !== 'number') {
  return {
    json: {
      target: 'failed',
      payload: {
        slack_message_id: slackTs,
        slack_channel: slackChannel,
        raw_input: rawInput,
        error_reason: parseError || 'gemini parse failed'
      },
      slack_ts: slackTs,
      slack_channel: slackChannel,
      gemini: gemini
    }
  };
}

const category = gemini.category; // 'Payment' | 'Expense' | 'Investment'

// Build target-specific payload
let target;
let payload;

if (category === 'Payment') {
  target = 'payments';
  payload = { slack_message_id: slackTs, raw_input: rawInput };
  if (gemini.amount !== undefined)          payload.amount = gemini.amount;
  if (gemini.student_phone !== undefined)   payload.student_phone = gemini.student_phone;
  if (gemini.student_name !== undefined)    payload.student_name = gemini.student_name;
  if (gemini.referrer_name !== undefined)   payload.referrer_name = gemini.referrer_name;
  if (gemini.is_partial !== undefined)      payload.is_partial = gemini.is_partial;
  // Fallback: if Gemini dropped referrer_name, extract from raw input ("ref X",
  // "referred by X"). Laravel requires it for new students (M5 validation).
  if (!payload.referrer_name) {
    const m = rawInput.match(/\bref(?:erred\s+by)?[:\s]\s*([A-Za-z][A-Za-z\s'.-]*?)(?:[,.!?]|$)/i);
    if (m) payload.referrer_name = m[1].trim();
  }
} else if (category === 'Expense') {
  target = 'expenses';
  payload = {
    amount: gemini.amount,
    category: gemini.expense_category || null,
    description: gemini.notes || null,
    slack_message_id: slackTs,
    raw_input: rawInput
  };
} else if (category === 'Investment') {
  target = 'investments';
  payload = {
    asset_name: gemini.asset_name || null,
    amount: gemini.amount,
    direction: (gemini.investment_direction || '').toLowerCase() || null,
    slack_message_id: slackTs,
    raw_input: rawInput
  };
}

return {
  json: {
    target,
    payload,
    slack_ts: slackTs,
    slack_channel: slackChannel,
    gemini
  }
};
